  /**
   * @method
   * @name bitstamp#cancelAllOrders
   * @description cancel all open orders
   * @see https://www.bitstamp.net/api/#tag/Orders/operation/CancelAllOrders
   * @see
   * https://www.bitstamp.net/api/#tag/Orders/operation/CancelOrdersForMarket
   * @param {string} [symbol] unified market symbol, only orders in the market
   * of this symbol are cancelled when symbol is not undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  cancelAllOrders(std::any symbol = std::any{},
                  std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any market = std::any{};
                        std::any request = ccxt::dict{};
                        std::any response = std::any{};
                        if (isTrue(!isEqual(symbol, std::any{}))) {
                          market = this->market(symbol);
                          ::setValue(request, std::string("pair"),
                                     ::getValue(market, std::string("id")));
                          response =
                              awaitValue(this->privatePostCancelAllOrdersPair(
                                  this->extend(request, params)));
                        } else {
                          response =
                              awaitValue(this->privatePostCancelAllOrders(
                                  this->extend(request, params)));
                        }
                        //
                        //    {
                        //        "canceled": [
                        //            {
                        //                "id": 1453282316578816,
                        //                "amount": "0.02035278",
                        //                "price": "2100.45",
                        //                "type": 0,
                        //                "currency_pair": "BTC/USD",
                        //                "market": "BTC/USD"
                        //            }
                        //        ],
                        //        "success": true
                        //    }
                        //
                        std::any canceled =
                            this->safeList(response, std::string("canceled"));
                        return this->parseOrders(canceled);
                      })
        .share();
  }

  virtual std::any parseOrderStatus(std::any status) {
    std::any statuses = ccxt::dict{
        {std::string("In Queue"), std::string("open")},
        {std::string("Open"), std::string("open")},
        {std::string("Finished"), std::string("closed")},
        {std::string("Canceled"), std::string("canceled")},
        {std::string("Cancel pending"), std::string("canceling")},
    };
    return this->safeString(statuses, status, status);
  }

  std::shared_future<std::any>
  fetchOrderStatus(std::any id, std::any symbol = std::any{},
                   std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any clientOrderId = this->safeValue2(
                            params, std::string("client_order_id"),
                            std::string("clientOrderId"));
                        std::any request = ccxt::dict{};
                        if (isTrue(!isEqual(clientOrderId, std::any{}))) {
                          ::setValue(request, std::string("client_order_id"),
                                     clientOrderId);
                          params = this->omit(
                              params, ccxt::list{std::string("client_order_id"),
                                                 std::string("clientOrderId")});
                        } else {
                          ::setValue(request, std::string("id"), id);
                        }
                        std::any response =
                            awaitValue(this->privatePostOrderStatus(
                                this->extend(request, params)));
                        return this->parseOrderStatus(
                            this->safeString(response, std::string("status")));
                      })
        .share();
  }

